        if (SharedConstants.DEBUG_VILLAGE_SECTIONS) {
            this.renderers.add(new VillageSectionsDebugRenderer());
        }
        if (SharedConstants.DEBUG_BRAIN) {
            this.renderers.add(new BrainDebugRenderer(minecraft));
        }
