        this.renderDistance = new OptionInstance<Integer>("options.renderDistance", OptionInstance.noTooltip(), (caption, value) -> Options.genericValueLabel(caption, (Component)Component.translatable((String)"options.chunks", (Object[])new Object[]{value})), new OptionInstance.IntRange(2, largeDistances ? 32 : 16, false), 12, n -> this.setGraphicsPresetToCustom());
