    /*
     * WARNING - Removed try catching itself - possible behaviour change.
     */
    public static int saveReport(File gameDirectory, CrashReport crash, int reportExitCode) {
        Path crashDir = gameDirectory.toPath().resolve("crash-reports");
        Path crashFile = crashDir.resolve("crash-" + Util.getFilenameFormattedDateTime() + "-client.txt");
        try {
            Bootstrap.realStdoutPrintln((String)crash.getFriendlyReport(ReportType.CRASH));
        }
        catch (Throwable t) {
            LOGGER.error("Failed to print exception", t);
        }
        LOGGER.debug("Disabling console - remaining logs will be available only in log file");
        try {
            if (crash.getSaveFile() != null) {
                Bootstrap.realStdoutPrintln((String)("#@!@# Game crashed! Crash report saved to: #@!@# " + String.valueOf(crash.getSaveFile().toAbsolutePath())));
                int n = reportExitCode;
                return n;
            }
            if (crash.saveToFile(crashFile, ReportType.CRASH)) {
                Bootstrap.realStdoutPrintln((String)("#@!@# Game crashed! Crash report saved to: #@!@# " + String.valueOf(crashFile.toAbsolutePath())));
                int n = reportExitCode;
                return n;
            }
            Bootstrap.realStdoutPrintln((String)"#@?@# Game crashed! Crash report could not be saved. #@?@#");
            int n = -2;
            return n;
        }
        finally {
            Bootstrap.shutdownStdout();
        }
    }

    public static void crash(@Nullable Minecraft minecraft, File gameDirectory, CrashReport crash, int exitCode) {
        int actualExitCode = Minecraft.saveReportAndShutdownSoundManager(minecraft, gameDirectory, crash, exitCode);
        System.exit(actualExitCode);
    }

    public static int saveReportAndShutdownSoundManager(@Nullable Minecraft minecraft, File gameDirectory, CrashReport crash, int exitCode) {
        int actualExitCode = Minecraft.saveReport(gameDirectory, crash, exitCode);
        if (minecraft != null) {
            minecraft.soundManager.emergencyShutdown();
        }
        return actualExitCode;
    }

