            int midX = this.leftPos + 9 + 117;
            graphics.centeredText(this.font, NO_ADVANCEMENTS_LABEL, midX, this.topPos + 18 + 56 - this.font.lineHeight / 2, -1);
            graphics.centeredText(this.font, VERY_SAD_LABEL, midX, this.topPos + 18 + 113 - this.font.lineHeight, -1);
