    private static final Component SNAPSHOT_TOOLTIP_2 = Component.translatable((String)"selectWorld.tooltip.snapshot2").withStyle(ChatFormatting.GOLD);
    private static final Component WORLD_LOCKED_TOOLTIP = Component.translatable((String)"selectWorld.locked").withStyle(ChatFormatting.RED);
    private static final Component WORLD_REQUIRES_CONVERSION = Component.translatable((String)"selectWorld.conversion.tooltip").withStyle(ChatFormatting.RED);
    private static final Component INCOMPATIBLE_VERSION_TOOLTIP = Component.translatable((String)"selectWorld.incompatible.tooltip").withStyle(ChatFormatting.RED);
    private static final Component WORLD_EXPERIMENTAL = Component.translatable((String)"selectWorld.experimental");
    private final Screen screen;
    private CompletableFuture<List<LevelSummary>> pendingLevels;
    private @Nullable List<LevelSummary> currentlyDisplayedLevels;
    private final LoadingHeader loadingHeader;
    private final EntryType entryType;
